#!/usr/bin/env python3
"""
Proof-of-Concept: Keystream Reuse DoS via SDCTR Misuse

This script demonstrates the vulnerability described in RFC 4344 Section 6.1,
where encrypting more than 2^L blocks with the same key in SDCTR mode causes
keystream reuse. This allows an attacker to XOR two ciphertexts to recover
the XOR of the plaintexts, potentially leading to data leakage or injection.

Note: This is a simulation of the cryptographic vulnerability. In a real attack,
the attacker would force a vulnerable SSH server to encrypt massive amounts of
data without rekeying.
"""

import os
import struct
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend

# Constants
BLOCK_SIZE_BYTES = 16  # AES block size (128 bits)
L = 128                # Block length in bits
MAX_BLOCKS = 2 ** L    # Maximum blocks before counter wraps (theoretical limit)

# For demonstration, we use a smaller counter space to simulate the wrap-around
# without requiring 2^128 blocks. We'll use a 32-bit counter for simulation.
SIMULATED_COUNTER_BITS = 32
SIMULATED_MAX_BLOCKS = 2 ** (SIMULATED_COUNTER_BITS // 8)

def generate_keystream(key, nonce, num_blocks):
    """
    Simulates SDCTR keystream generation.
    In real SSH SDCTR, the counter is incremented for each block.
    """
    # Initialize AES in CTR mode with a fixed nonce and starting counter
    # Note: Real SSH SDCTR uses a specific counter format. We simplify for PoC.
    counter = 0
    keystream = b''
    
    # Create AES cipher
    cipher = Cipher(algorithms.AES(key), modes.CTR(nonce), backend=default_backend())
    encryptor = cipher.encryptor()
    
    # Generate keystream blocks
    for _ in range(num_blocks):
        # In CTR mode, encrypting the counter value produces the keystream block
        # We simulate counter increment by generating blocks sequentially
        block = encryptor.update(b'\x00' * BLOCK_SIZE_BYTES)
        keystream += block
        counter += 1
        
        # Simulate counter wrap-around for demonstration
        if counter >= SIMULATED_MAX_BLOCKS:
            print(f"[!] Counter wrapped around after {counter} blocks!")
            # In a vulnerable implementation, the counter would reset or wrap,
            # causing keystream reuse. Here, we simulate by restarting the cipher
            # with the same nonce, which effectively reuses the keystream.
            cipher = Cipher(algorithms.AES(key), modes.CTR(nonce), backend=default_backend())
            encryptor = cipher.encryptor()
            counter = 0
            
    return keystream

def encrypt_message(key, nonce, plaintext):
    """
    Encrypts a message using the simulated SDCTR keystream.
    """
    num_blocks = (len(plaintext) + BLOCK_SIZE_BYTES - 1) // BLOCK_SIZE_BYTES
    keystream = generate_keystream(key, nonce, num_blocks)
    
    # XOR plaintext with keystream
    ciphertext = bytes(a ^ b for a, b in zip(plaintext, keystream[:len(plaintext)]))
    return ciphertext

def main():
    print("[*] Keystream Reuse DoS via SDCTR Misuse - Proof of Concept")
    print("[*] Simulating vulnerable SSH server behavior...")
    
    # Generate a random key and nonce
    key = os.urandom(32)  # 256-bit AES key
    nonce = os.urandom(16)  # 128-bit nonce
    
    # Define two different plaintext messages
    plaintext1 = b"Sensitive data: Password123!"
    plaintext2 = b"Sensitive data: CreditCard456!"
    
    print(f"[*] Plaintext 1: {plaintext1.decode()}")
    print(f"[*] Plaintext 2: {plaintext2.decode()}")
    
    # Encrypt both messages with the same key and nonce
    # In a vulnerable scenario, the server would encrypt massive amounts of data
    # without rekeying, eventually causing keystream reuse.
    # Here, we simulate the wrap-around by forcing the counter to reset.
    
    # First, generate enough keystream to cause wrap-around
    print(f"[*] Generating {SIMULATED_MAX_BLOCKS} blocks to trigger counter wrap...")
    generate_keystream(key, nonce, SIMULATED_MAX_BLOCKS)
    
    # Now, encrypt the two messages. Due to the simulated wrap-around,
    # the keystream will be reused.
    print("[*] Encrypting messages after counter wrap (keystream reused)...")
    ciphertext1 = encrypt_message(key, nonce, plaintext1)
    ciphertext2 = encrypt_message(key, nonce, plaintext2)
    
    print(f"[*] Ciphertext 1: {ciphertext1.hex()}")
    print(f"[*] Ciphertext 2: {ciphertext2.hex()}")
    
    # Demonstrate keystream reuse attack: XOR ciphertexts to get XOR of plaintexts
    print("[*] Performing keystream reuse attack...")
    xor_result = bytes(a ^ b for a, b in zip(ciphertext1, ciphertext2))
    print(f"[*] XOR of ciphertexts: {xor_result.hex()}")
    
    # The XOR of the ciphertexts equals the XOR of the plaintexts
    expected_xor = bytes(a ^ b for a, b in zip(plaintext1, plaintext2))
    print(f"[*] Expected XOR of plaintexts: {expected_xor.hex()}")
    
    if xor_result == expected_xor:
        print("[!] SUCCESS: Keystream reuse detected! XOR of ciphertexts matches XOR of plaintexts.")
        print("[!] An attacker can now use known-plaintext or statistical attacks to recover sensitive data.")
    else:
        print("[?] Unexpected result. Keystream reuse may not have occurred as simulated.")
    
    print("[*] Demonstration complete.")

if __name__ == "__main__":
    main()